assert($("#task-msg").textContent === "" && !$("#task-msg").classList.contains("error"), "Görev eklenince hata mesajı ve error sınıfı temizlenmeli.");
assert($("#task-input").value === "", "Görev eklenince kutu boşalmalı (form.reset()).");

